(5261924, 765812, 33068, '<td valign="top">Nice vintage looking shot.</td>', 'Nice vintage looking shot.', '2009-02-18 00:36:19.000000', NULL, 1),
(5261930, 766233, 61961, '<td valign="top">Pretty sky, but I think the lack of sharpness in the foreground detracts from the overall impact.</td>', 'Pretty sky, but I think the lack of sharpness in the foreground detracts from the overall impact.', '2009-02-18 00:38:01.000000', NULL, 1),
