(5273355, 765792, 15511, '<td valign="top">I almost went there. Rain "dampened" my enthusiasm, but it works for this shot.</td>', 'I almost went there. Rain "dampened" my enthusiasm, but it works for this shot.', '2009-02-25 00:34:43.000000', NULL, 0),
(5273367, 766310, 52449, '<td valign="top">Yes, indeed--this was a popular gas station. In fact, in my research, this is the only outdoor vintage station in LA and Orange Counties. There are some museums with vintage gasoline pumps, by they are all inside lined-up on display which doesn''t make for great composition. Good showing (Top 20!).</td>', 'Yes, indeed--this was a popular gas station. In fact, in my research, this is the only outdoor vintage station in LA and Orange Counties. There are some museums with vintage gasoline pumps, by they are all inside lined-up on display which doesn''t make for great composition. Good showing (Top 20!).', '2009-02-25 00:37:56.000000', NULL, 0),
(5273368, 765650, 98171, '<td valign="top">I saw your post in the score thread so I hurried and looked to see if I could pick yours out, and sure enough, this was the one I saw that was the best. Congrats!</td>', 'I saw your post in the score thread so I hurried and looked to see if I could pick yours out, and sure enough, this was the one I saw that was the best. Congrats!', '2009-02-25 00:38:01.000000', NULL, 0),
